import { Component, ElementRef, Renderer2 } from '@angular/core';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-search',
  standalone: true,
  imports: [FormsModule],
  template: `
    <form class="search" role="search" (submit)="handleSearch($event)">
      <label for="site-search" class="sr-only">Search the site</label>
      <input id="site-search" type="search" name="q" [(ngModel)]="searchQuery" placeholder="Search query">
      <input type="submit" value="Go!">
    </form>
  `,
  styles: []
})
export class SearchComponent {
  searchQuery = '';

  constructor(private elementRef: ElementRef, private renderer: Renderer2) {}

  handleSearch(event: Event): void {
    event.preventDefault();

    try {
      // Clear previous highlights
      document.querySelectorAll('.highlight').forEach((el) => {
        const parent = el.parentNode;
        if (parent !== null) {
          parent.replaceChild(
            document.createTextNode(el.textContent ?? ''),
            el
          );
          parent.normalize();
        }
      });

      const searchKey = this.searchQuery.trim();
      if (searchKey === '') return;

      const regex = new RegExp(
        '(' + searchKey.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')',
        'gi'
      );

      const walk = (node: Node): void => {
        if (node.nodeType === 3) {
          // Text node
          const nodeValue = node.nodeValue ?? '';
          const match = nodeValue.match(regex);
          if (match !== null) {
            const span = document.createElement('span');
            span.innerHTML = nodeValue.replace(
              regex,
              '<mark class="highlight">$1</mark>'
            );
            const parentNode = node.parentNode;
            if (parentNode !== null) {
              parentNode.replaceChild(span, node);
            }
          }
        } else if (
          node.nodeType === 1 &&
          (node as Element).tagName !== 'SCRIPT' &&
          (node as Element).tagName !== 'STYLE' &&
          (node as Element).tagName !== 'FORM'
        ) {
          node.childNodes.forEach(walk);
        }
      };

      // Only search within article content
      const articleElement = document.querySelector('article');
      if (articleElement !== null) {
        walk(articleElement);
      }
    } catch (error) {
      console.error('Search error:', error);
      alert('Search failed. Please try a different search term.');
    }
  }
}
